Review this change. File: `internal/cache/lru.go`. What the change does: Adds a size-bounded LRU cache with a per-entry TTL, shared by all request goroutines in the API server.

Line numbers are on the left of the `|`.

```go
 1 | package cache
 2 | 
 3 | import (
 4 | 	"container/list"
 5 | 	"sync"
 6 | 	"time"
 7 | )
 8 | 
 9 | type entry struct {
10 | 	key     string
11 | 	value   []byte
12 | 	expires time.Time
13 | }
14 | 
15 | type Cache struct {
16 | 	mu    sync.RWMutex
17 | 	items map[string]*list.Element
18 | 	order *list.List
19 | 	max   int
20 | 	ttl   time.Duration
21 | }
22 | 
23 | func New(max int, ttl time.Duration) *Cache {
24 | 	return &Cache{items: make(map[string]*list.Element), order: list.New(), max: max, ttl: ttl}
25 | }
26 | 
27 | func (c *Cache) Get(key string) ([]byte, bool) {
28 | 	c.mu.RLock()
29 | 	defer c.mu.RUnlock()
30 | 	el, ok := c.items[key]
31 | 	if !ok {
32 | 		return nil, false
33 | 	}
34 | 	e := el.Value.(*entry)
35 | 	if time.Now().After(e.expires) {
36 | 		return nil, false
37 | 	}
38 | 	c.order.MoveToFront(el)
39 | 	return e.value, true
40 | }
41 | 
42 | func (c *Cache) Set(key string, value []byte) {
43 | 	c.mu.Lock()
44 | 	defer c.mu.Unlock()
45 | 	if el, ok := c.items[key]; ok {
46 | 		e := el.Value.(*entry)
47 | 		e.value = value
48 | 		c.order.MoveToFront(el)
49 | 		return
50 | 	}
51 | 	el := c.order.PushFront(&entry{key: key, value: value, expires: time.Now().Add(c.ttl)})
52 | 	c.items[key] = el
53 | 	if c.order.Len() > c.max {
54 | 		last := c.order.Back()
55 | 		c.order.Remove(last)
56 | 	}
57 | }
58 | 
59 | func (c *Cache) Delete(key string) {
60 | 	c.mu.Lock()
61 | 	el := c.items[key]
62 | 	c.order.Remove(el)
63 | 	delete(c.items, key)
64 | 	c.mu.Unlock()
65 | }
66 | 
67 | func (c *Cache) Len() int {
68 | 	return len(c.items)
69 | }
