Review this change. File: `internal/events/broker.go`. What the change does: In-memory pub/sub that pushes live updates to browsers over SSE. Topics are named 'user:<id>' and are private to that user; auth middleware stores the caller's id, readable with auth.UserID(r.Context()). Slow subscribers may drop messages but must never block publishers. Close() runs on shutdown while clients are still connected. Messages are JSON and can contain newlines.

Line numbers are on the left of the `|`.

```go
 1 | package events
 2 | 
 3 | import (
 4 | 	"context"
 5 | 	"fmt"
 6 | 	"net/http"
 7 | 	"sync"
 8 | 	"time"
 9 | )
10 | 
11 | type Broker struct {
12 | 	mu     sync.Mutex
13 | 	subs   map[string]map[chan []byte]struct{}
14 | 	closed bool
15 | }
16 | 
17 | func New() *Broker {
18 | 	return &Broker{subs: map[string]map[chan []byte]struct{}{}}
19 | }
20 | 
21 | func (b *Broker) Subscribe(ctx context.Context, topic string) <-chan []byte {
22 | 	ch := make(chan []byte, 16)
23 | 	b.mu.Lock()
24 | 	if b.subs[topic] == nil {
25 | 		b.subs[topic] = map[chan []byte]struct{}{}
26 | 	}
27 | 	b.subs[topic][ch] = struct{}{}
28 | 	b.mu.Unlock()
29 | 
30 | 	go func() {
31 | 		<-ctx.Done()
32 | 		b.mu.Lock()
33 | 		delete(b.subs[topic], ch)
34 | 		b.mu.Unlock()
35 | 
36 | 		close(ch)
37 | 	}()
38 | 	return ch
39 | }
40 | 
41 | func (b *Broker) Publish(topic string, msg []byte) {
42 | 	b.mu.Lock()
43 | 	defer b.mu.Unlock()
44 | 	if b.closed {
45 | 		return
46 | 	}
47 | 	for ch := range b.subs[topic] {
48 | 		ch <- msg
49 | 	}
50 | }
51 | 
52 | func (b *Broker) Close() {
53 | 	b.mu.Lock()
54 | 	defer b.mu.Unlock()
55 | 	b.closed = true
56 | 	for _, set := range b.subs {
57 | 		for ch := range set {
58 | 			close(ch)
59 | 		}
60 | 	}
61 | }
62 | 
63 | func (b *Broker) ReportEvery(ctx context.Context, d time.Duration, report func(map[string]int)) {
64 | 	t := time.NewTicker(d)
65 | 	for {
66 | 		select {
67 | 		case <-ctx.Done():
68 | 			return
69 | 		case <-t.C:
70 | 			counts := map[string]int{}
71 | 			b.mu.Lock()
72 | 			for topic, set := range b.subs {
73 | 				counts[topic] = len(set)
74 | 			}
75 | 			b.mu.Unlock()
76 | 			report(counts)
77 | 		}
78 | 	}
79 | }
80 | 
81 | func (b *Broker) ServeSSE(w http.ResponseWriter, r *http.Request) {
82 | 	topic := r.URL.Query().Get("topic")
83 | 	flusher, ok := w.(http.Flusher)
84 | 	if !ok {
85 | 		http.Error(w, "streaming unsupported", http.StatusInternalServerError)
86 | 		return
87 | 	}
88 | 	w.Header().Set("Content-Type", "text/event-stream")
89 | 	w.Header().Set("Cache-Control", "no-cache")
90 | 
91 | 	for msg := range b.Subscribe(r.Context(), topic) {
92 | 		fmt.Fprintf(w, "data: %s\n\n", msg)
93 | 		flusher.Flush()
94 | 	}
95 | }
